-- ============================================
-- BM Iphone Store Stock - Full Import
-- Source: BM Iphone Store Stock.xlsx
-- Total items: 281
-- Store: BM Iphone Store (a0000000-0000-0000-0000-000000000002)
-- Run this in Supabase SQL Editor
-- ============================================

DELETE FROM public.stock_lots WHERE store_id = 'a0000000-0000-0000-0000-000000000002';
DELETE FROM public.stock WHERE store_id = 'a0000000-0000-0000-0000-000000000002';

-- 2. Insert stock items

-- 3. Create opening stock lots for FIFO sales deduction
SELECT 
  'IPH-' || code, 
  NULL, 
  code, 
  name, 
  CURRENT_DATE, 
  'IMPORT', 
  qty, 
  purchase_price, 
  store_id
FROM public.stock
WHERE store_id = 'a0000000-0000-0000-0000-000000000002'
ON CONFLICT DO NOTHING;

-- 4. Sync sequences with imported stock data
SELECT setval('public.stock_code_seq', GREATEST(1, (SELECT COALESCE(MAX(CAST(code AS integer)), 0) FROM public.stock)));
SELECT setval('public.lot_no_seq', GREATEST(1, (SELECT COALESCE(MAX(CAST(SUBSTRING(lot_no FROM 5) AS integer)), 0) FROM public.stock_lots)));
